#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "bicg.h"

/* Tunable blocking factor for the inner (j) loop in the BiCG kernel.
   This does not change the arithmetic order with respect to the
   original code (j is still traversed from 0 to M-1 in increasing
   order for every i), but allows the traversal to be structured in
   cache-sized chunks when beneficial.

   You can experiment with values such as 64, 128, 256, 512 depending
   on the target machine's L1/L2 cache size and the problem dimensions. */
#ifndef BICG_J_BLOCK
# define BICG_J_BLOCK 256
#endif


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  /* Local restrict-qualified pointers to help the compiler with alias
     analysis. All PolyBench arrays are allocated disjointly. */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE *restrict r_ = r;
  DATA_TYPE *restrict p_ = p;

  /* Precompute reciprocals to avoid repeated divisions. */
  const DATA_TYPE inv_m = (DATA_TYPE)1.0 / (DATA_TYPE)m;
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;

  /* Note: for 0 <= i < m, (i % m) == i, so the following preserves the
     exact arithmetic of the original code:
       p[i] = (DATA_TYPE)(i % m) / m;  ->  p[i] = (DATA_TYPE)i / m; */
  for (i = 0; i < m; i++)
    p_[i] = (DATA_TYPE)i * inv_m;

  /* Similarly, for 0 <= i < n, (i % n) == i and
       r[i] = (DATA_TYPE)(i % n) / n;  ->  r[i] = (DATA_TYPE)i / n;
     The initialization of A is unchanged, except we reuse inv_n. */
  for (i = 0; i < n; i++) {
    r_[i] = (DATA_TYPE)i * inv_n;
    DATA_TYPE *restrict Ai = A_[i];
    for (j = 0; j < m; j++)
      Ai[j] = (DATA_TYPE)((i * (j + 1)) % n) * inv_n;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use local restrict-qualified pointers to express that the PolyBench
     arrays do not alias. This enables more aggressive vectorization
     and reordering by the compiler.
   - Hoist invariant loads (r[i], A[i]) out of the inner loop.
   - Use a scalar accumulator 'qi' for q[i] and store it once after the
     inner loop, rather than repeatedly updating q[i] in memory.
   - Introduce a tunable blocking of the j dimension (BICG_J_BLOCK)
     while strictly preserving the original (i,j) iteration order.
     This preserves floating-point accumulation order and thus keeps
     numerical results bitwise identical, while enabling cache-friendly
     traversals on some architectures.
*/
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* Cache the (possibly macro-based) loop bounds locally. */
  const int Mdim = _PB_M;
  const int Ndim = _PB_N;

  /* Local restrict-qualified views of the arrays. Types are identical
     to the function parameters; only the pointer qualifier changes. */
  DATA_TYPE (*restrict A_)[m]   = A;
  DATA_TYPE *restrict s_        = s;
  DATA_TYPE *restrict q_        = q;
  const DATA_TYPE *restrict p_  = p;
  const DATA_TYPE *restrict r_  = r;

#pragma scop
  /* Initialize s once. */
  for (i = 0; i < Mdim; i++)
    s_[i] = (DATA_TYPE)0;

  /* BiCG kernel: q = A * p;  s = A^T * r. */
  for (i = 0; i < Ndim; i++)
    {
      const DATA_TYPE ri = r_[i];
      const DATA_TYPE *restrict Ai = A_[i];
      DATA_TYPE qi = (DATA_TYPE)0;

      /* Optional j-blocking controlled by BICG_J_BLOCK. This keeps the
         logical order of (i,j) iterations identical to the original
         code: for each i, j still runs from 0 to Mdim-1 in increasing
         order, only split into contiguous blocks. */
      for (int jb = 0; jb < Mdim; jb += BICG_J_BLOCK)
	{
	  const int j_end = (jb + BICG_J_BLOCK < Mdim) ?
	                    (jb + BICG_J_BLOCK) : Mdim;

#pragma GCC ivdep
	  for (j = jb; j < j_end; j++)
	    {
	      const DATA_TYPE Aij = Ai[j];
	      s_[j] += ri * Aij;
	      qi    += Aij * p_[j];
	    }
	}

      q_[i] = qi;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_bicg (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(s),
	       POLYBENCH_ARRAY(q),
	       POLYBENCH_ARRAY(p),
	       POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}
