 *
 * Contact:
 *   Louis-Noel Pouchet <pouchet.ohio-state.edu>
 *   Tomofumi Yuki <tomofumi.yuki.fr>
 *
 * Web address: http://polybench.sourceforge.net
 */
/* bicg.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "bicg.h"

/* --------------------------------------------------------------------
 * Tunable kernel parameters
 *
 * BICG_COL_BLOCK controls the cache-blocking factor along the column
 * dimension (M).  It should be chosen so that two blocks
 *   - s_block[BICG_COL_BLOCK]
 *   - p_block[BICG_COL_BLOCK]
 * comfortably fit in L1 cache.
 *
 * For double precision, BICG_COL_BLOCK = 64 → 64 * 8 B * 2 ≈ 1 KiB.
 * Feel free to tune this constant for a particular machine.
 * ------------------------------------------------------------------ */
#ifndef BICG_COL_BLOCK
# define BICG_COL_BLOCK 64
#endif

_Static_assert(BICG_COL_BLOCK > 0, "BICG_COL_BLOCK must be > 0");


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  for (i = 0; i < m; i++)
    p[i] = (DATA_TYPE)(i % m) / m;
  for (i = 0; i < n; i++) {
    r[i] = (DATA_TYPE)(i % n) / n;
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % n)/n;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version:
   ------------------
   The original kernel performs a single pass over A and computes

     s[j] = sum_i r[i] * A[i][j]   (A^T * r)
     q[i] = sum_j A[i][j] * p[j]   (A * p)

   with the following structure:

     s[:] = 0;
     for i
       q[i] = 0;
       for j
         s[j] += r[i] * A[i][j];
         q[i] += A[i][j] * p[j];

   This already has good locality for A (row-major) but performs
   a lot of memory traffic on vectors s and p: each element is
   touched once per row of A.

   The optimized kernel below:
   - Preserves the exact per-element floating-point evaluation order.
   - Introduces cache blocking along the column dimension (M) using
     BICG_COL_BLOCK.
   - Keeps small tiles of s and p in fast stack storage
     (s_block and p_block), so:
       * Each element of p and s is loaded/stored only once.
       * Each A[i][j] is still read exactly once (no extra passes).
   - Uses restrict-qualified local pointers and a vectorization hint
     (GCC ivdep) to help the compiler generate efficient SIMD code.
*/
static
void kernel_bicg [[gnu::flatten, gnu::noinline]] (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* Local restricted views to help the optimizer.
     In this benchmark, all arrays are distinct and non-overlapping,
     so these restrict qualifiers reflect the actual usage. */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE *restrict s_ = s;
  DATA_TYPE *restrict q_ = q;
  DATA_TYPE *restrict p_ = p;
  DATA_TYPE *restrict r_ = r;

#pragma scop
  /* Preserve the original explicit initialization of s.
     This also ensures correct behavior when _PB_M == 0. */
  for (i = 0; i < _PB_M; i++)
    s_[i] = SCALAR_VAL(0.0);

  /* q[i] was initialized inside the outer loop in the original code.
     Initializing it once here is equivalent but slightly cheaper. */
  for (i = 0; i < _PB_N; i++)
    q_[i] = SCALAR_VAL(0.0);

  const int Mdim = _PB_M;
  const int Ndim = _PB_N;

  /* Small column tiles kept on the stack.  Their size is controlled
     by BICG_COL_BLOCK so it can be tuned per architecture. */
  DATA_TYPE s_block[BICG_COL_BLOCK];
  DATA_TYPE p_block[BICG_COL_BLOCK];

  /* Cache-blocked traversal.
     Outer loop over column tiles [j0, j0 + jb). For each tile:
       1) Load the corresponding slice of p into p_block.
       2) Zero the partial sums s_block.
       3) For every row i:
            - update s_block with r[i] * A[i][j],
            - update q[i] with A[i][j] * p_block[j].
       4) Store s_block back into s.

     For each fixed (i, j), the updates to s[j] and q[i] occur in the
     same order as in the original kernel; only the interleaving across
     different indices changes, which does not affect the result because
     those elements live in distinct memory locations. */
  for (int j0 = 0; j0 < Mdim; j0 += BICG_COL_BLOCK)
    {
      const int jb = (j0 + BICG_COL_BLOCK <= Mdim) ?
                     BICG_COL_BLOCK : (Mdim - j0);

      /* Load p tile and reset s partial sums for this tile. */
      for (j = 0; j < jb; ++j)
        {
          p_block[j] = p_[j0 + j];
          s_block[j] = SCALAR_VAL(0.0);
        }

      /* Process all rows for the current column tile. */
      for (i = 0; i < Ndim; ++i)
        {
          const DATA_TYPE r_i = r_[i];
          DATA_TYPE q_i = q_[i]; /* Current partial sum for row i. */

          const DATA_TYPE *restrict A_row = &A_[i][j0];

          /* Inner loop over the small column tile.
             - No loop-carried dependencies across j.
             - q_i is a scalar reduction.
             The ivdep pragma tells GCC that there are no
             vectorization-inhibiting dependencies. */
#pragma GCC ivdep
          for (j = 0; j < jb; ++j)
            {
              const DATA_TYPE A_ij = A_row[j];
              s_block[j] += r_i * A_ij;
              q_i        += A_ij * p_block[j];
            }

          q_[i] = q_i;
        }

      /* Commit the accumulated s values for this column tile. */
      for (j = 0; j < jb; ++j)
        s_[j0 + j] = s_block[j];
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_bicg (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(s),
	       POLYBENCH_ARRAY(q),
	       POLYBENCH_ARRAY(p),
	       POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
