 *  - Hoist invariant loads (r[i] and A[i]) out of the inner loop.
 *  - Use a temporary for A[i][j] to avoid multiple loads of the same
 *    element within the iteration.
 *  - Keep the (i,j) traversal order identical to the original code so
 *    that the sequence of floating-point operations for each element
 *    of s[] and q[] remains the same.
 *  - Add a compiler hint (#pragma GCC ivdep) to aid vectorization of
 *    the inner loop; iterations are independent across j.
 */
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
                 DATA_TYPE POLYBENCH_1D(s,M,m),
                 DATA_TYPE POLYBENCH_1D(q,N,n),
                 DATA_TYPE POLYBENCH_1D(p,M,m),
                 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* Local restrict-qualified views of the vectors.
     In PolyBench, these arrays are allocated disjointly, so treating them
     as non-aliasing is valid and enables better optimization. */
  DATA_TYPE *restrict s_ = s;
  DATA_TYPE *restrict q_ = q;
  DATA_TYPE *restrict p_ = p;
  DATA_TYPE *restrict r_ = r;

#pragma scop
  /* Initialize s to zero. */
  for (i = 0; i < _PB_M; i++)
    s_[i] = SCALAR_VAL(0.0);

  /* BiCG kernel:
     q[i] = sum_j A[i][j] * p[j]
     s[j] = sum_i r[i] * A[i][j]
   */
  for (i = 0; i < _PB_N; i++)
    {
      /* Load invariants for this row once. */
      DATA_TYPE ri = r_[i];
      DATA_TYPE qi = SCALAR_VAL(0.0);
      DATA_TYPE *Ai = A[i];

