#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "bicg.h"

/* Tunable blocking factor for the j-dimension in kernel_bicg.
 *
 * This controls how many consecutive columns of A (and corresponding
 * entries of p and s) are processed together inside the innermost
 * loop.  It can be adjusted to better fit the target machine's cache
 * hierarchy (e.g., L1 data cache).
 *
 * Reasonable values are typically in the range [32, 256].  The
 * correctness of the computation does not depend on this value.
 */
#ifndef BICG_J_BLOCK_SIZE
# define BICG_J_BLOCK_SIZE 64
#endif


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  for (i = 0; i < m; i++)
    p[i] = (DATA_TYPE)(i % m) / m;
  for (i = 0; i < n; i++) {
    r[i] = (DATA_TYPE)(i % n) / n;
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % n)/n;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#pragma scop
  /* Use local constants for the PolyBench-sized problem.  This makes
     the bounds explicit to the compiler and avoids re-expanding the
     macros in every loop header. */
  const int pb_m = _PB_M;
  const int pb_n = _PB_N;

  /* Local restricted views of the data.
   *
   * PolyBench guarantees that these arrays are allocated in
   * disjoint memory regions, so it is safe to mark the local
   * pointers as 'restrict'.  This gives the compiler more freedom
   * to reorder and vectorize memory accesses.
   */
  DATA_TYPE * restrict s_ = s;
  DATA_TYPE * restrict q_ = q;
  DATA_TYPE * restrict p_ = p;
  DATA_TYPE * restrict r_ = r;
  DATA_TYPE * restrict A_flat = (DATA_TYPE*)A;

  /* Initialize s to zero.  Kept as a simple counted loop so that
     the compiler can trivially vectorize it. */
  for (i = 0; i < pb_m; i++)
    s_[i] = SCALAR_VAL(0.0);

  /* Main BiCG kernel:
       q[i] = sum_j A[i][j] * p[j]
       s[j] = sum_i r[i] * A[i][j]
   *
   * We keep the original computation order (i outer, j inner) so that
   * we traverse rows of A contiguously in memory, which is optimal for
   * row-major storage.  Within the j-dimension we apply blocking to
   * improve locality for s and p when M is large.
   */
  for (i = 0; i < pb_n; i++)
    {
      const DATA_TYPE r_i = r_[i];
      DATA_TYPE q_i = SCALAR_VAL(0.0);

      /* Pointer to the beginning of row i of A in the flattened view. */
      DATA_TYPE * restrict row = A_flat + (size_t)i * (size_t)pb_m;

      /* Block the j-dimension.  This preserves the original
         left-to-right order of j, so the floating-point reduction
         order (and thus the numerical result apart from normal
         rounding effects) is unchanged. */
      for (int jb = 0; jb < pb_m; jb += BICG_J_BLOCK_SIZE)
        {
          const int j_end = (jb + BICG_J_BLOCK_SIZE < pb_m)
                            ? (jb + BICG_J_BLOCK_SIZE)
                            : pb_m;

          /* Inner j-loop: both updates reuse the loaded A(i,j) value.
             The ivdep pragma tells GCC there are no loop-carried
             dependencies that prevent vectorization. */
          #pragma GCC ivdep
          for (j = jb; j < j_end; j++)
            {
              const DATA_TYPE a_ij = row[j];

              /* s[j] += r[i] * A[i][j]; */
              s_[j] += r_i * a_ij;

              /* q[i] += A[i][j] * p[j]; (accumulated in q_i) */
              q_i += a_ij * p_[j];
            }
        }

      /* Store the accumulated result for this row. */
      q_[i] = q_i;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
